// Minimises stored personal data: the author identifier is hashed and the
// message is truncated. No names, avatars or profile links are retained.
const pub = $('SPLIT - Publications').first().json;
const raw = $input.first().json || {};
const crypto = require('crypto');
const since = Date.now() - 6 * 3600 * 1000;
const out = [];
for (const c of (raw.data || [])) {
  const ts = new Date(c.created_time).getTime();
  if (!Number.isFinite(ts) || ts < since) continue;
  if (!c.message || !String(c.message).trim()) continue;
  out.push({
    json: {
      publication_id: pub.publication_id,
      client_id: pub.client_id,
      campaign_id: pub.campaign_id,
      platform: pub.platform,
      business_name: pub.business_name,
      brand_voice: pub.brand_voice,
      interaction_type: 'comment',
      external_id: c.id,
      author_hash: crypto.createHash('sha256').update(String(c.from?.id || c.id)).digest('hex').slice(0, 32),
      message: String(c.message).slice(0, 1000),
      received_at: new Date(ts).toISOString()
    }
  });
}
return out;

const idx = $itemIndex;
const src = $('CODE - Extract New Comments').all()[idx]?.json || $('CODE - Extract New Comments').first().json;
const raw = $json;
const CATS = ['question', 'complaint', 'praise', 'purchase_intent', 'spam', 'other'];
const BANNED = [/\brefund\b/i, /\bdiscount\b/i, /\bguarantee\b/i, /\bfree of charge\b/i, /\bwe will deliver\b/i, /\bcure\b/i];
let p = null;
try { p = JSON.parse(String(raw?.choices?.[0]?.message?.content || '').replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); } catch (e) { p = null; }

const errors = [];
if (!p) errors.push('unparseable_output');
else {
  if (!CATS.includes(p.category)) errors.push('category_invalid');
  if (!['positive', 'neutral', 'negative'].includes(p.sentiment)) errors.push('sentiment_invalid');
  if (!['low', 'medium', 'high'].includes(p.urgency)) errors.push('urgency_invalid');
  if (typeof p.draft_response !== 'string' || !p.draft_response.trim()) errors.push('draft_missing');
  if (p.draft_response && p.draft_response.length > 600) errors.push('draft_too_long');
  for (const re of BANNED) if (re.test(String(p.draft_response || ''))) errors.push('prohibited_commitment');
}

const requiresHuman = true; // Candidate responses are ALWAYS reviewed. Nothing is auto-sent.
return {
  json: {
    ...src,
    classification: p ? { category: p.category, sentiment: p.sentiment, urgency: p.urgency, model_flagged_human: !!p.requires_human, reasoning: p.reasoning } : null,
    draft_response: errors.length === 0 ? p.draft_response : null,
    review_state: 'pending_review',
    requires_human: requiresHuman,
    validation_errors: errors,
    model_version: $env.OPENAI_MODEL || 'gpt-4.1'
  }
};
